package com.minhnb.finvera_be.alert.service;
import com.minhnb.finvera_be.alert.config.AlertProperties;import java.util.*;import org.slf4j.*;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Component;
@Component@ConditionalOnProperty(prefix="finvera.alert.worker",name="enabled",havingValue="true",matchIfMissing=true)
public class AlertWorker{private static final Logger log=LoggerFactory.getLogger(AlertWorker.class);private final AlertClaimService claims;private final AlertEvaluationService eval;private final AlertProperties props;public AlertWorker(AlertClaimService c,AlertEvaluationService e,AlertProperties p){claims=c;eval=e;props=p;}
 @Scheduled(fixedDelayString="${finvera.alert.worker.poll-delay:10s}")public void poll(){for(var claim:claims.claim(props.batchSize(),props.leaseDuration())){try{eval.evaluate(claim.alertId(),claim.leaseToken(),props.pollDelay());}catch(Exception ex){log.warn("alert_evaluation_failed type={} reason=EVALUATION_ERROR",ex.getClass().getSimpleName());eval.fail(claim.alertId(),claim.leaseToken(),props.maxAttempts(),props.pollDelay());}}}
 @Scheduled(fixedDelayString="${finvera.alert.worker.recovery-delay:30s}")public void recover(){for(var claim:claims.recoverExpired(props.batchSize(),props.maxAttempts(),props.leaseDuration()))try{eval.fail(claim.alertId(),claim.leaseToken(),props.maxAttempts(),props.pollDelay());}catch(Exception ex){log.warn("alert_recovery_failed type={} reason=RECOVERY_ERROR",ex.getClass().getSimpleName());}}
}
